DROP DATABASE IF EXISTS tiendas3a;
CREATE DATABASE tiendas3a CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci;
USE tiendas3a;

CREATE TABLE caja (
    caja_id        INT AUTO_INCREMENT PRIMARY KEY,
    codigo         VARCHAR(10)  NOT NULL UNIQUE,
    serie_boleta   VARCHAR(4)   NOT NULL UNIQUE,
    serie_factura  VARCHAR(4)   NOT NULL UNIQUE,
    activo         BOOLEAN      NOT NULL DEFAULT TRUE
) ENGINE = InnoDB;

CREATE TABLE usuario (
    usuario_id         INT AUTO_INCREMENT PRIMARY KEY,
    nombre             VARCHAR(120) NOT NULL,
    nombre_acceso      VARCHAR(60)  NOT NULL UNIQUE,
    clave_hash         VARCHAR(255) NOT NULL,
    rol                VARCHAR(20)  NOT NULL,
    intentos_fallidos  INT          NOT NULL DEFAULT 0,
    bloqueado_hasta    DATETIME     NULL,
    activo             BOOLEAN      NOT NULL DEFAULT TRUE,
    creado_en          DATETIME     NOT NULL,
    CONSTRAINT ck_usuario_rol CHECK (rol IN ('CAJERO', 'ADMINISTRADOR')),
    CONSTRAINT ck_usuario_intentos CHECK (intentos_fallidos >= 0)
) ENGINE = InnoDB;

CREATE TABLE categoria (
    categoria_id  INT AUTO_INCREMENT PRIMARY KEY,
    nombre        VARCHAR(80)  NOT NULL UNIQUE,
    descripcion   VARCHAR(200) NULL,
    activo        BOOLEAN      NOT NULL DEFAULT TRUE
) ENGINE = InnoDB;

CREATE TABLE producto (
    producto_id    INT AUTO_INCREMENT PRIMARY KEY,
    categoria_id   INT            NOT NULL,
    codigo         VARCHAR(40)    NOT NULL UNIQUE,
    nombre         VARCHAR(120)   NOT NULL,
    unidad_medida  VARCHAR(10)    NOT NULL,
    precio_venta   DECIMAL(12,2)  NOT NULL,
    stock_actual   DECIMAL(12,3)  NOT NULL,
    activo         BOOLEAN        NOT NULL DEFAULT TRUE,
    CONSTRAINT fk_producto_categoria FOREIGN KEY (categoria_id) REFERENCES categoria (categoria_id),
    CONSTRAINT ck_producto_precio CHECK (precio_venta > 0),
    CONSTRAINT ck_producto_stock CHECK (stock_actual >= 0),
    CONSTRAINT ck_producto_unidad CHECK (unidad_medida IN ('UNIDAD', 'KG'))
) ENGINE = InnoDB;

CREATE TABLE promocion (
    promocion_id        INT AUTO_INCREMENT PRIMARY KEY,
    producto_id         INT            NOT NULL,
    nombre              VARCHAR(80)    NOT NULL,
    precio_promocional  DECIMAL(12,2)  NOT NULL,
    fecha_inicio        DATE           NOT NULL,
    fecha_fin           DATE           NOT NULL,
    creado_por          INT            NOT NULL,
    activo              BOOLEAN        NOT NULL DEFAULT TRUE,
    CONSTRAINT fk_promocion_producto FOREIGN KEY (producto_id) REFERENCES producto (producto_id),
    CONSTRAINT fk_promocion_usuario FOREIGN KEY (creado_por) REFERENCES usuario (usuario_id),
    CONSTRAINT ck_promocion_precio CHECK (precio_promocional > 0),
    CONSTRAINT ck_promocion_fechas CHECK (fecha_fin >= fecha_inicio)
) ENGINE = InnoDB;

CREATE TABLE cliente (
    cliente_id           INT AUTO_INCREMENT PRIMARY KEY,
    tipo_documento       VARCHAR(5)   NOT NULL,
    numero_documento     VARCHAR(11)  NOT NULL,
    nombre_razon_social  VARCHAR(150) NOT NULL,
    direccion            VARCHAR(200) NULL,
    activo               BOOLEAN      NOT NULL DEFAULT TRUE,
    CONSTRAINT uq_cliente_documento UNIQUE (tipo_documento, numero_documento),
    CONSTRAINT ck_cliente_tipo CHECK (tipo_documento IN ('DNI', 'RUC'))
) ENGINE = InnoDB;

CREATE TABLE cierre_caja (
    cierre_caja_id     INT AUTO_INCREMENT PRIMARY KEY,
    usuario_id         INT            NOT NULL,
    caja_id            INT            NOT NULL,
    fecha              DATE           NOT NULL,
    fecha_hora_cierre  DATETIME       NOT NULL,
    fondo_inicial      DECIMAL(12,2)  NOT NULL,
    cantidad_ventas    INT            NOT NULL,
    cantidad_anuladas  INT            NOT NULL,
    total_efectivo     DECIMAL(12,2)  NOT NULL,
    total_tarjeta      DECIMAL(12,2)  NOT NULL,
    total_billetera    DECIMAL(12,2)  NOT NULL,
    devuelto_efectivo  DECIMAL(12,2)  NOT NULL,
    efectivo_esperado  DECIMAL(12,2)  NOT NULL,
    efectivo_contado   DECIMAL(12,2)  NOT NULL,
    diferencia         DECIMAL(12,2)  NOT NULL,
    observacion        VARCHAR(250)   NULL,
    CONSTRAINT uq_cierre_dia UNIQUE (usuario_id, caja_id, fecha),
    CONSTRAINT fk_cierre_usuario FOREIGN KEY (usuario_id) REFERENCES usuario (usuario_id),
    CONSTRAINT fk_cierre_caja FOREIGN KEY (caja_id) REFERENCES caja (caja_id),
    CONSTRAINT ck_cierre_observacion CHECK (diferencia = 0 OR (observacion IS NOT NULL AND observacion <> ''))
) ENGINE = InnoDB;

CREATE TABLE venta (
    venta_id          INT AUTO_INCREMENT PRIMARY KEY,
    caja_id           INT            NOT NULL,
    usuario_id        INT            NOT NULL,
    cliente_id        INT            NULL,
    cierre_caja_id    INT            NULL,
    fecha_hora        DATETIME       NOT NULL,
    estado            VARCHAR(15)    NOT NULL,
    subtotal          DECIMAL(12,2)  NOT NULL,
    igv               DECIMAL(12,2)  NOT NULL,
    total             DECIMAL(12,2)  NOT NULL,
    clave_operacion   VARCHAR(64)    NOT NULL UNIQUE,
    fecha_anulacion   DATETIME       NULL,
    motivo_anulacion  VARCHAR(250)   NULL,
    anulado_por       INT            NULL,
    CONSTRAINT fk_venta_caja FOREIGN KEY (caja_id) REFERENCES caja (caja_id),
    CONSTRAINT fk_venta_usuario FOREIGN KEY (usuario_id) REFERENCES usuario (usuario_id),
    CONSTRAINT fk_venta_cliente FOREIGN KEY (cliente_id) REFERENCES cliente (cliente_id),
    CONSTRAINT fk_venta_cierre FOREIGN KEY (cierre_caja_id) REFERENCES cierre_caja (cierre_caja_id),
    CONSTRAINT fk_venta_anulado_por FOREIGN KEY (anulado_por) REFERENCES usuario (usuario_id),
    CONSTRAINT ck_venta_estado CHECK (estado IN ('EN_CURSO', 'CONFIRMADA', 'CANCELADA', 'ANULADA')),
    CONSTRAINT ck_venta_total CHECK (total = subtotal + igv),
    CONSTRAINT ck_venta_anulacion CHECK (estado <> 'ANULADA'
        OR (motivo_anulacion IS NOT NULL AND fecha_anulacion IS NOT NULL AND anulado_por IS NOT NULL))
) ENGINE = InnoDB;

CREATE TABLE detalle_venta (
    detalle_venta_id  INT AUTO_INCREMENT PRIMARY KEY,
    venta_id          INT            NOT NULL,
    producto_id       INT            NOT NULL,
    promocion_id      INT            NULL,
    cantidad          DECIMAL(12,3)  NOT NULL,
    precio_lista      DECIMAL(12,2)  NOT NULL,
    precio_unitario   DECIMAL(12,2)  NOT NULL,
    importe           DECIMAL(12,2)  NOT NULL,
    CONSTRAINT uq_detalle_producto UNIQUE (venta_id, producto_id),
    CONSTRAINT fk_detalle_venta FOREIGN KEY (venta_id) REFERENCES venta (venta_id),
    CONSTRAINT fk_detalle_producto FOREIGN KEY (producto_id) REFERENCES producto (producto_id),
    CONSTRAINT fk_detalle_promocion FOREIGN KEY (promocion_id) REFERENCES promocion (promocion_id),
    CONSTRAINT ck_detalle_cantidad CHECK (cantidad > 0),
    CONSTRAINT ck_detalle_precio CHECK (precio_unitario <= precio_lista)
) ENGINE = InnoDB;

CREATE TABLE pago (
    pago_id               INT AUTO_INCREMENT PRIMARY KEY,
    venta_id              INT            NOT NULL UNIQUE,
    usuario_id            INT            NOT NULL,
    fecha_hora            DATETIME       NOT NULL,
    medio                 VARCHAR(15)    NOT NULL,
    monto                 DECIMAL(12,2)  NOT NULL,
    monto_entregado       DECIMAL(12,2)  NULL,
    vuelto                DECIMAL(12,2)  NULL,
    referencia_digital    VARCHAR(100)   NULL,
    estado                VARCHAR(15)    NOT NULL,
    fecha_reversion       DATETIME       NULL,
    revertido_por         INT            NULL,
    cierre_reversion_id   INT            NULL,
    referencia_reversion  VARCHAR(100)   NULL,
    CONSTRAINT fk_pago_venta FOREIGN KEY (venta_id) REFERENCES venta (venta_id),
    CONSTRAINT fk_pago_usuario FOREIGN KEY (usuario_id) REFERENCES usuario (usuario_id),
    CONSTRAINT fk_pago_revertido_por FOREIGN KEY (revertido_por) REFERENCES usuario (usuario_id),
    CONSTRAINT fk_pago_cierre FOREIGN KEY (cierre_reversion_id) REFERENCES cierre_caja (cierre_caja_id),
    CONSTRAINT ck_pago_medio CHECK (medio IN ('EFECTIVO', 'TARJETA', 'BILLETERA')),
    CONSTRAINT ck_pago_estado CHECK (estado IN ('REGISTRADO', 'REVERTIDO')),
    CONSTRAINT ck_pago_efectivo CHECK (medio <> 'EFECTIVO' OR monto_entregado >= monto),
    CONSTRAINT ck_pago_referencia CHECK (medio = 'EFECTIVO' OR referencia_digital IS NOT NULL),
    CONSTRAINT ck_pago_reversion CHECK (estado <> 'REVERTIDO' OR (fecha_reversion IS NOT NULL AND revertido_por IS NOT NULL))
) ENGINE = InnoDB;

CREATE TABLE comprobante (
    comprobante_id        INT AUTO_INCREMENT PRIMARY KEY,
    venta_id              INT           NOT NULL UNIQUE,
    tipo                  VARCHAR(12)   NOT NULL,
    serie                 VARCHAR(4)    NOT NULL,
    correlativo           INT           NOT NULL,
    fecha_emision         DATETIME      NOT NULL,
    estado                VARCHAR(10)   NOT NULL,
    intentos_envio        INT           NOT NULL DEFAULT 0,
    fecha_ultimo_envio    DATETIME      NULL,
    fecha_respuesta       DATETIME      NULL,
    observacion_sunat     VARCHAR(250)  NULL,
    observacion_revision  VARCHAR(250)  NULL,
    CONSTRAINT uq_comprobante_numero UNIQUE (serie, correlativo),
    CONSTRAINT fk_comprobante_venta FOREIGN KEY (venta_id) REFERENCES venta (venta_id),
    CONSTRAINT ck_comprobante_tipo CHECK (tipo IN ('VENTA_SIMPLE', 'BOLETA', 'FACTURA')),
    CONSTRAINT ck_comprobante_estado CHECK (estado IN ('PENDIENTE', 'ACEPTADO', 'RECHAZADO', 'ANULADO'))
) ENGINE = InnoDB;

CREATE TABLE movimiento_inventario (
    movimiento_id     INT AUTO_INCREMENT PRIMARY KEY,
    producto_id       INT            NOT NULL,
    detalle_venta_id  INT            NOT NULL,
    usuario_id        INT            NOT NULL,
    fecha_hora        DATETIME       NOT NULL,
    tipo              VARCHAR(20)    NOT NULL,
    cantidad          DECIMAL(12,3)  NOT NULL,
    saldo_resultante  DECIMAL(12,3)  NOT NULL,
    CONSTRAINT fk_movimiento_producto FOREIGN KEY (producto_id) REFERENCES producto (producto_id),
    CONSTRAINT fk_movimiento_detalle FOREIGN KEY (detalle_venta_id) REFERENCES detalle_venta (detalle_venta_id),
    CONSTRAINT fk_movimiento_usuario FOREIGN KEY (usuario_id) REFERENCES usuario (usuario_id),
    CONSTRAINT ck_movimiento_cantidad CHECK (cantidad > 0),
    CONSTRAINT ck_movimiento_tipo CHECK (tipo IN ('SALIDA_VENTA', 'REINGRESO_ANULACION'))
) ENGINE = InnoDB;

CREATE TABLE auditoria (
    auditoria_id  INT AUTO_INCREMENT PRIMARY KEY,
    usuario_id    INT          NULL,
    fecha_hora    DATETIME     NOT NULL,
    accion        VARCHAR(40)  NOT NULL,
    entidad       VARCHAR(40)  NOT NULL,
    registro_id   VARCHAR(64)  NULL,
    resultado     VARCHAR(20)  NOT NULL,
    detalle       TEXT         NULL,
    CONSTRAINT fk_auditoria_usuario FOREIGN KEY (usuario_id) REFERENCES usuario (usuario_id),
    CONSTRAINT ck_auditoria_resultado CHECK (resultado IN ('EXITO', 'FALLIDO', 'RECHAZADO'))
) ENGINE = InnoDB;

CREATE INDEX ix_venta_fecha ON venta (fecha_hora);
CREATE INDEX ix_comprobante_estado ON comprobante (estado);
CREATE INDEX ix_auditoria_fecha ON auditoria (fecha_hora);














SELECT 'usuario' AS tabla, COUNT(*) AS registros FROM usuario
UNION ALL SELECT 'producto', COUNT(*) FROM producto
UNION ALL SELECT 'venta', COUNT(*) FROM venta
UNION ALL SELECT 'comprobante', COUNT(*) FROM comprobante
UNION ALL SELECT 'cierre_caja', COUNT(*) FROM cierre_caja
UNION ALL SELECT 'auditoria', COUNT(*) FROM auditoria;
